-- Durable backing for Calendar, Food Delivery, Okada, Contributions, Leaderboard,
-- Town News, Courses, and Market Stalls. All debits remain server-authoritative.
create table public.town_events (id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null check(length(btrim(title)) between 3 and 120), venue text not null check(length(btrim(venue)) between 2 and 120), starts_at timestamptz not null, created_at timestamptz not null default now());
create table public.player_event_reminders (user_id uuid not null references public.profiles(id) on delete cascade, event_id uuid not null references public.town_events(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,event_id));
create table public.food_vendors (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null unique check(length(btrim(name)) between 2 and 80), active boolean not null default true);
create table public.food_menu_items (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.food_vendors(id) on delete cascade, name text not null check(length(btrim(name)) between 2 and 100), price_minor bigint not null check(price_minor>0), active boolean not null default true, unique(vendor_id,name));
create table public.food_orders (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, character_id uuid not null references public.characters(id) on delete cascade, vendor_id uuid not null references public.food_vendors(id), total_minor bigint not null check(total_minor>0), status text not null check(status in ('requested','preparing','delivered','cancelled')), created_at timestamptz not null default now());
create table public.food_order_items (order_id uuid not null references public.food_orders(id) on delete cascade, menu_item_id uuid not null references public.food_menu_items(id), quantity integer not null check(quantity between 1 and 20), unit_price_minor bigint not null check(unit_price_minor>0), primary key(order_id,menu_item_id));
create table public.town_service_prices (service text primary key check(service in ('okada_ride')), amount_minor bigint not null check(amount_minor>0), active boolean not null default true);
create table public.okada_ride_requests (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, character_id uuid not null references public.characters(id) on delete cascade, destination text not null check(length(btrim(destination)) between 2 and 120), fare_minor bigint not null check(fare_minor>0), status text not null check(status in ('requested','assigned','completed','cancelled')), created_at timestamptz not null default now());
create table public.community_funds (id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null check(length(btrim(title)) between 3 and 120), goal_minor bigint not null check(goal_minor>0), active boolean not null default true);
create table public.community_contributions (id uuid primary key default gen_random_uuid(), fund_id uuid not null references public.community_funds(id), user_id uuid not null references public.profiles(id) on delete cascade, character_id uuid not null references public.characters(id) on delete cascade, amount_minor bigint not null check(amount_minor>0), created_at timestamptz not null default now());
create table public.town_news_posts (id uuid primary key default gen_random_uuid(), author_user_id uuid references public.profiles(id) on delete set null, category text not null check(category in ('Community','Market','Sports','General')), title text not null check(length(btrim(title)) between 3 and 120), body text not null check(length(btrim(body)) between 3 and 1000), created_at timestamptz not null default now());
create table public.town_news_reactions (post_id uuid not null references public.town_news_posts(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(post_id,user_id));
create table public.town_news_comments (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.town_news_posts(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, body text not null check(length(btrim(body)) between 1 and 400), created_at timestamptz not null default now());
create table public.player_course_plans (user_id uuid not null references public.profiles(id) on delete cascade, character_id uuid not null references public.characters(id) on delete cascade, course_id uuid not null references public.education_courses(id) on delete cascade, planned_at timestamptz not null default now(), primary key(character_id,course_id));
create table public.npc_market_stalls (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null check(length(btrim(name)) between 2 and 64), goods text not null check(length(btrim(goods)) between 2 and 200), status text not null check(status in ('open','busy','closed')), visitor_count integer not null default 0 check(visitor_count>=0));
create table public.player_stalls (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.profiles(id) on delete cascade, character_id uuid not null unique references public.characters(id) on delete cascade, name text not null check(length(btrim(name)) between 2 and 64), goods text not null check(length(btrim(goods)) between 2 and 200), is_open boolean not null default false, updated_at timestamptz not null default now());
create index food_orders_character_created_idx on public.food_orders(character_id,created_at desc); create index ride_requests_character_created_idx on public.okada_ride_requests(character_id,created_at desc); create index contribution_fund_created_idx on public.community_contributions(fund_id,created_at desc); create index news_posts_created_idx on public.town_news_posts(created_at desc); create index news_comments_post_created_idx on public.town_news_comments(post_id,created_at);
alter table public.town_events enable row level security; alter table public.player_event_reminders enable row level security; alter table public.food_vendors enable row level security; alter table public.food_menu_items enable row level security; alter table public.food_orders enable row level security; alter table public.food_order_items enable row level security; alter table public.town_service_prices enable row level security; alter table public.okada_ride_requests enable row level security; alter table public.community_funds enable row level security; alter table public.community_contributions enable row level security; alter table public.town_news_posts enable row level security; alter table public.town_news_reactions enable row level security; alter table public.town_news_comments enable row level security; alter table public.player_course_plans enable row level security; alter table public.npc_market_stalls enable row level security; alter table public.player_stalls enable row level security;
grant select on public.town_events,public.food_vendors,public.food_menu_items,public.town_service_prices,public.community_funds,public.town_news_posts,public.town_news_reactions,public.town_news_comments,public.npc_market_stalls,public.player_stalls to authenticated; grant select on public.player_event_reminders,public.food_orders,public.food_order_items,public.okada_ride_requests,public.community_contributions,public.player_course_plans to authenticated; grant all on public.town_events,public.player_event_reminders,public.food_vendors,public.food_menu_items,public.food_orders,public.food_order_items,public.town_service_prices,public.okada_ride_requests,public.community_funds,public.community_contributions,public.town_news_posts,public.town_news_reactions,public.town_news_comments,public.player_course_plans,public.npc_market_stalls,public.player_stalls to service_role;
create policy "phone read events" on public.town_events for select to authenticated using(true); create policy "phone own reminders" on public.player_event_reminders for select to authenticated using((select auth.uid())=user_id); create policy "phone read vendors" on public.food_vendors for select to authenticated using(active); create policy "phone read menu" on public.food_menu_items for select to authenticated using(active); create policy "phone own orders" on public.food_orders for select to authenticated using((select auth.uid())=user_id); create policy "phone own order items" on public.food_order_items for select to authenticated using(exists(select 1 from public.food_orders o where o.id=order_id and o.user_id=(select auth.uid()))); create policy "phone read prices" on public.town_service_prices for select to authenticated using(active); create policy "phone own rides" on public.okada_ride_requests for select to authenticated using((select auth.uid())=user_id); create policy "phone read funds" on public.community_funds for select to authenticated using(active); create policy "phone own contributions" on public.community_contributions for select to authenticated using((select auth.uid())=user_id); create policy "phone read news" on public.town_news_posts for select to authenticated using(true); create policy "phone read reactions" on public.town_news_reactions for select to authenticated using(true); create policy "phone read comments" on public.town_news_comments for select to authenticated using(true); create policy "phone own plans" on public.player_course_plans for select to authenticated using((select auth.uid())=user_id); create policy "phone read npc stalls" on public.npc_market_stalls for select to authenticated using(true); create policy "phone read player stalls" on public.player_stalls for select to authenticated using(is_open or user_id=(select auth.uid()));
