insert into public.education_courses(slug,name,provider,description,tuition,energy_cost,intelligence_gain,career_gain,sort_order) values ('phone-repair-basics','Phone Repair Basics','Osun Tech Hub','Learn practical diagnostics and common mobile repairs.',2400,18,4,5,20),('fashion-and-tailoring','Fashion and Tailoring','Aro Craft School','Build skills for measured cuts, finishing, and customer work.',3000,22,3,6,21),('catering-essentials','Catering Essentials','Iya Mufu Kitchen','Learn kitchen planning, food safety, and service basics.',2600,20,4,5,22),('digital-marketing','Digital Marketing','Osun Tech Hub','Practice campaign planning and local business promotion.',3200,20,6,5,23),('solar-installation','Solar Installation','Community Polytechnic','Study safe installation, maintenance, and customer support.',4200,26,7,6,24) on conflict(slug) do update set name=excluded.name,provider=excluded.provider,description=excluded.description,tuition=excluded.tuition,energy_cost=excluded.energy_cost,intelligence_gain=excluded.intelligence_gain,career_gain=excluded.career_gain,sort_order=excluded.sort_order;
create or replace function public.save_phone_event_reminder(p_event_id uuid,p_enabled boolean) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); begin if uid is null then raise exception 'Sign in first'; end if; if not exists(select 1 from public.town_events where id=p_event_id) then raise exception 'Event not found'; end if; if coalesce(p_enabled,false) then insert into public.player_event_reminders(user_id,event_id) values(uid,p_event_id) on conflict do nothing; else delete from public.player_event_reminders where user_id=uid and event_id=p_event_id; end if; return jsonb_build_object('eventId',p_event_id,'enabled',coalesce(p_enabled,false)); end $$;
create or replace function public.plan_phone_course(p_course_slug text) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); cid uuid:=public._my_character_id(); course_id uuid; begin if uid is null or cid is null then raise exception 'Sign in and create a character first'; end if; select id into course_id from public.education_courses where slug=p_course_slug; if course_id is null then raise exception 'Course not found'; end if; insert into public.player_course_plans(user_id,character_id,course_id) values(uid,cid,course_id) on conflict(character_id,course_id) do update set planned_at=now(); return jsonb_build_object('courseSlug',p_course_slug,'planned',true); end $$;
create or replace function public.save_player_stall(p_name text,p_goods text,p_is_open boolean) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); cid uuid:=public._my_character_id(); clean_name text:=btrim(coalesce(p_name,'')); clean_goods text:=btrim(coalesce(p_goods,'')); begin if uid is null or cid is null then raise exception 'Sign in and create a character first'; end if; if length(clean_name) not between 2 and 64 or length(clean_goods) not between 2 and 200 then raise exception 'Use a stall name of 2 to 64 characters and goods of 2 to 200 characters'; end if; insert into public.player_stalls(user_id,character_id,name,goods,is_open) values(uid,cid,clean_name,clean_goods,coalesce(p_is_open,false)) on conflict(user_id) do update set name=excluded.name,goods=excluded.goods,is_open=excluded.is_open,updated_at=now(); return jsonb_build_object('ok',true,'isOpen',coalesce(p_is_open,false)); end $$;
create or replace function public.create_town_news_post(p_category text,p_title text,p_body text) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); post_id uuid; clean_title text:=btrim(coalesce(p_title,'')); clean_body text:=btrim(coalesce(p_body,'')); begin if uid is null then raise exception 'Sign in first'; end if; if p_category not in ('Community','Market','Sports','General') or length(clean_title) not between 3 and 120 or length(clean_body) not between 3 and 1000 then raise exception 'Check the post category, title, and body length'; end if; insert into public.town_news_posts(author_user_id,category,title,body) values(uid,p_category,clean_title,clean_body) returning id into post_id; return jsonb_build_object('id',post_id); end $$;
create or replace function public.toggle_town_news_reaction(p_post_id uuid,p_reacted boolean) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); begin if uid is null then raise exception 'Sign in first'; end if; if not exists(select 1 from public.town_news_posts where id=p_post_id) then raise exception 'Post not found'; end if; if coalesce(p_reacted,false) then insert into public.town_news_reactions(post_id,user_id) values(p_post_id,uid) on conflict do nothing; else delete from public.town_news_reactions where post_id=p_post_id and user_id=uid; end if; return jsonb_build_object('postId',p_post_id,'reacted',coalesce(p_reacted,false)); end $$;
create or replace function public.create_town_news_comment(p_post_id uuid,p_body text) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); comment_id uuid; clean_body text:=btrim(coalesce(p_body,'')); begin if uid is null then raise exception 'Sign in first'; end if; if not exists(select 1 from public.town_news_posts where id=p_post_id) then raise exception 'Post not found'; end if; if length(clean_body) not between 1 and 400 then raise exception 'Comment must be 1 to 400 characters'; end if; insert into public.town_news_comments(post_id,user_id,body) values(p_post_id,uid,clean_body) returning id into comment_id; return jsonb_build_object('id',comment_id); end $$;
create or replace function public.request_food_delivery(p_vendor_id uuid,p_items jsonb,p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare uid uuid:=auth.uid(); cid uuid:=public._my_character_id(); vendor public.food_vendors%rowtype; wallet public.wallets%rowtype; line record; item public.food_menu_items%rowtype; total bigint:=0; order_id uuid; cash_after bigint; result jsonb;
begin
 if uid is null or cid is null then raise exception 'Sign in and create a character first'; end if;
 if p_request_id is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Choose menu items and include a request ID'; end if;
 perform pg_advisory_xact_lock(hashtextextended(cid::text||p_request_id::text,0));
 select er.result into result from public.economy_request_results er where er.character_id=cid and er.request_id=p_request_id and er.operation='food_delivery'; if found then return result; end if;
 select * into vendor from public.food_vendors where id=p_vendor_id and active for update; if not found then raise exception 'Vendor is unavailable'; end if;
 for line in select * from jsonb_to_recordset(p_items) as x(menu_item_id uuid,quantity integer) loop
  if line.quantity is null or line.quantity not between 1 and 20 then raise exception 'Each food quantity must be from 1 to 20'; end if;
  select * into item from public.food_menu_items where id=line.menu_item_id and vendor_id=vendor.id and active;
  if not found then raise exception 'Menu item is unavailable'; end if; total:=total+item.price_minor*line.quantity;
 end loop;
 select * into wallet from public.wallets where character_id=cid and user_id=uid for update; if not found or wallet.balance<total then raise exception 'Insufficient cash'; end if;
 cash_after:=wallet.balance-total; update public.wallets set balance=cash_after,total_expenses=total_expenses+total where id=wallet.id;
 insert into public.food_orders(user_id,character_id,vendor_id,total_minor,status) values(uid,cid,vendor.id,total,'requested') returning id into order_id;
 for line in select * from jsonb_to_recordset(p_items) as x(menu_item_id uuid,quantity integer) loop select * into item from public.food_menu_items where id=line.menu_item_id; insert into public.food_order_items(order_id,menu_item_id,quantity,unit_price_minor) values(order_id,item.id,line.quantity,item.price_minor); end loop;
 insert into public.transactions(user_id,wallet_id,character_id,amount,kind,category,description,transaction_type,account,source,destination,balance_after,metadata) values(uid,wallet.id,cid,total,'expense','food_delivery','Food delivery from '||vendor.name,'purchase','cash',vendor.name,'food_delivery',cash_after,jsonb_build_object('order_id',order_id,'request_id',p_request_id));
 result:=jsonb_build_object('orderId',order_id,'total',total,'cash',cash_after,'status','requested'); insert into public.economy_request_results(character_id,request_id,operation,result) values(cid,p_request_id,'food_delivery',result); return result;
end $$;
create or replace function public.request_okada_ride(p_destination text,p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare uid uuid:=auth.uid(); cid uuid:=public._my_character_id(); wallet public.wallets%rowtype; fare bigint; ride_id uuid; cash_after bigint; destination_text text:=btrim(coalesce(p_destination,'')); result jsonb;
begin
 if uid is null or cid is null then raise exception 'Sign in and create a character first'; end if; if p_request_id is null or length(destination_text) not between 2 and 120 then raise exception 'Choose a destination and include a request ID'; end if;
 perform pg_advisory_xact_lock(hashtextextended(cid::text||p_request_id::text,0)); select er.result into result from public.economy_request_results er where er.character_id=cid and er.request_id=p_request_id and er.operation='okada_ride'; if found then return result; end if;
 select amount_minor into fare from public.town_service_prices where service='okada_ride' and active for update; if fare is null then raise exception 'Okada rides are unavailable'; end if;
 select * into wallet from public.wallets where character_id=cid and user_id=uid for update; if not found or wallet.balance<fare then raise exception 'Insufficient cash'; end if; cash_after:=wallet.balance-fare; update public.wallets set balance=cash_after,total_expenses=total_expenses+fare where id=wallet.id;
 insert into public.okada_ride_requests(user_id,character_id,destination,fare_minor,status) values(uid,cid,destination_text,fare,'requested') returning id into ride_id;
 insert into public.transactions(user_id,wallet_id,character_id,amount,kind,category,description,transaction_type,account,source,destination,balance_after,metadata) values(uid,wallet.id,cid,fare,'expense','transport','Okada ride to '||destination_text,'purchase','cash','Okada rides',destination_text,cash_after,jsonb_build_object('ride_id',ride_id,'request_id',p_request_id));
 result:=jsonb_build_object('rideId',ride_id,'fare',fare,'cash',cash_after,'status','requested'); insert into public.economy_request_results(character_id,request_id,operation,result) values(cid,p_request_id,'okada_ride',result); return result;
end $$;
create or replace function public.contribute_to_community_fund(p_fund_id uuid,p_amount_minor bigint,p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare uid uuid:=auth.uid(); cid uuid:=public._my_character_id(); wallet public.wallets%rowtype; fund public.community_funds%rowtype; contribution_id uuid; cash_after bigint; result jsonb;
begin
 if uid is null or cid is null then raise exception 'Sign in and create a character first'; end if; if p_request_id is null or p_amount_minor is null or p_amount_minor not between 100 and 1000000 then raise exception 'Contribution must be from 100 to 1,000,000 and include a request ID'; end if;
 perform pg_advisory_xact_lock(hashtextextended(cid::text||p_request_id::text,0)); select er.result into result from public.economy_request_results er where er.character_id=cid and er.request_id=p_request_id and er.operation='community_contribution'; if found then return result; end if;
 select * into fund from public.community_funds where id=p_fund_id and active for update; if not found then raise exception 'Fund is unavailable'; end if; select * into wallet from public.wallets where character_id=cid and user_id=uid for update; if not found or wallet.balance<p_amount_minor then raise exception 'Insufficient cash'; end if;
 cash_after:=wallet.balance-p_amount_minor; update public.wallets set balance=cash_after,total_expenses=total_expenses+p_amount_minor where id=wallet.id; insert into public.community_contributions(fund_id,user_id,character_id,amount_minor) values(fund.id,uid,cid,p_amount_minor) returning id into contribution_id;
 insert into public.transactions(user_id,wallet_id,character_id,amount,kind,category,description,transaction_type,account,source,destination,balance_after,metadata) values(uid,wallet.id,cid,p_amount_minor,'expense','community','Contribution to '||fund.title,'transfer','cash','wallet',fund.title,cash_after,jsonb_build_object('contribution_id',contribution_id,'fund_id',fund.id,'request_id',p_request_id));
 result:=jsonb_build_object('contributionId',contribution_id,'amount',p_amount_minor,'cash',cash_after); insert into public.economy_request_results(character_id,request_id,operation,result) values(cid,p_request_id,'community_contribution',result); return result;
end $$;
create or replace function public.get_town_leaderboard() returns jsonb language sql stable security definer set search_path=public as $$ select coalesce(jsonb_agg(jsonb_build_object('rank',rank,'name',name,'score',score) order by rank),'[]'::jsonb) from (select row_number() over(order by(c.level*100+c.xp) desc,c.name) as rank,c.name,(c.level*100+c.xp)::bigint as score from public.characters c where c.name is not null order by(c.level*100+c.xp) desc,c.name limit 50) leaderboard $$;
revoke all on function public.save_phone_event_reminder(uuid,boolean),public.plan_phone_course(text),public.save_player_stall(text,text,boolean),public.create_town_news_post(text,text,text),public.toggle_town_news_reaction(uuid,boolean),public.create_town_news_comment(uuid,text),public.request_food_delivery(uuid,jsonb,uuid),public.request_okada_ride(text,uuid),public.contribute_to_community_fund(uuid,bigint,uuid),public.get_town_leaderboard() from public,anon;
grant execute on function public.save_phone_event_reminder(uuid,boolean),public.plan_phone_course(text),public.save_player_stall(text,text,boolean),public.create_town_news_post(text,text,text),public.toggle_town_news_reaction(uuid,boolean),public.create_town_news_comment(uuid,text),public.request_food_delivery(uuid,jsonb,uuid),public.request_okada_ride(text,uuid),public.contribute_to_community_fund(uuid,bigint,uuid),public.get_town_leaderboard() to authenticated;
